package ru.neverland.archaeology;
import java.util.*;import org.bukkit.Material;import org.bukkit.configuration.file.YamlConfiguration;import ru.neverland.archaeology.model.*;import ru.neverland.archaeology.restoration.*;
public final class TargetedSearchSmoke {
    static int checks;static void check(boolean value,String why){if(!value)throw new AssertionError(why);checks++;}static DigSite site(UUID world,int x,String type){return new DigSite(UUID.randomUUID(),type,world,"world",x,64,0,1000);}
    public static void main(String[] args){UUID world=UUID.randomUUID(),other=UUID.randomUUID();var definition=new SiteDefinition("ruins","Руины",Set.of(),Material.SUSPICIOUS_GRAVEL,Set.of(),1,1,Map.of("clay_seal",1,"old_coin",2));var rows=new ArrayList<DigSite>();var nearest=site(world,10,"ruins");rows.add(nearest);rows.add(site(other,1,"ruins"));rows.add(site(world,5,"unknown"));var finished=site(world,2,"ruins");finished.completed(true);rows.add(finished);rows.add(site(world,5001,"ruins"));for(int i=1;i<=20;i++)rows.add(site(world,20+i,"ruins"));var found=TargetedSearch.find("clay_seal",world,0,64,0,5000,rows,List.of(definition));check(found.size()==10&&found.get(0).site().equals(nearest.id()),"bounded nearest results ignore completed sites, unknown definitions and foreign worlds");check(found.get(0).knownAt()==1000&&found.get(0).possibleArtifacts().equals(Set.of("clay_seal","old_coin")),"provenance retains site age and possibility rather than promising actual loot");check(TargetedSearch.find("nonexistent",world,0,64,0,5000,rows,List.of(definition)).isEmpty(),"unknown artifact is not inferred from another type");check(TargetedSearch.find("clay_seal",world,0,64,0,5001,rows,List.of(definition)).isEmpty(),"radius cannot bypass metadata search bound");check(TargetedSearch.find("clay_seal",world,Integer.MIN_VALUE,64,0,5000,List.of(site(world,Integer.MAX_VALUE,"ruins")),List.of(definition)).isEmpty(),"coordinate subtraction does not overflow into a nearby fake result");
        var config=new YamlConfiguration();var defaults=RestorationSettings.read(config);check(defaults.chance()==0.15&&defaults.player24h()==6&&defaults.server24h()==120&&defaults.mailbox()==30,"additional fragment emission has explicit conservative defaults");var frozen=defaults.recipe("clay_seal","common");config.set("restoration.parts.common",8);var changed=RestorationSettings.read(config);check(frozen.parts()==3&&changed.recipe("clay_seal","common").parts()==8,"config only changes recipes of future findings");config.set("restoration.chance-per-brushed-block",Double.NaN);try{RestorationSettings.read(config);throw new AssertionError("NaN accepted");}catch(IllegalArgumentException expected){checks++;}System.out.println("TargetedSearchSmoke PASS "+checks+" checks");
    }
}
